/**
 * The full credit (with the source URL) for a credit line printed on a card, or
 * null if `content` is not one of ours. The on-card line shows only the domain;
 * the Maker's inspector uses this to show the whole URL when that line is
 * selected (TASK-26i).
 */
export function fullCreditFor(content: string): string | null {
  const trimmed = content.trim();
  for (const img of Object.values(READY_MADE_IMAGES)) {
    if (creditLine(img) === trimmed) return creditFull(img);
  }
  return null;
}
